            if (i == j) p[i][j] = 1;
            else { p[i][j] = 0; p[j][i] = 0; }
        }
    }
    n = 6;

    for (int mask = 0; mask < (1 << 18); ++mask) {
        ll prob1 = 1, prob2 = 1;
        int bm1 = 0, bm2 = 0;
        for (int j = 0; j < 6; ++j) {
            for (int k = 0; k < 3; ++k) {
