            if (ok) bm1 ^= (1 << ot);
        }
        for (int ot = 0; ot < 20; ++ot) {
            int ord[3] = {0, 1, 2};
            bool ok = false;
            do {
                bool ok2 = true;
                for (int j = 0; j < 3; ++j) {
